def compare_one(a, b):
    def to_float(x):
        if isinstance(x, str):
            s = x.strip()
            if ',' in s:
                parts = s.split(',')
                if len(parts) == 2 and parts[1].isdigit():
                    s = s.replace(',', '.')
                else:
                    s = s.replace(',', '')
            return float(s)
        return float(x)

    fa = to_float(a)
    fb = to_float(b)

    if abs(fa - fb) < 1e-12:
        return None
    return a if fa > fb else b
